"""English request -> program pairs for the OLED language, generated by rules and checked by the interpreter.

Each family is one kind of easy thing a person asks a matchbox-sized screen for (write a word, count down, draw a
circle, a frame, stripes, a moving dot, a progress bar…). A family draws its parameters, phrases the request one
of several ways, and writes the program in one of a few styles. Every program is run by lang.run before it is
kept: it must parse, stay in the language, finish in time and light at least one pixel.

Writes data/oled/pairs.jsonl: {prompt, program, family, doc}. doc is what the model learns:
"# <request>\\n<program>", ended later by the tokenizer's end-of-text.

    python -m research.oled.gen --n 300000
"""
import argparse
import json
import math
import random
import re
import string
import sys
from pathlib import Path

from .lang import CW, EYES, H, W, IO0, Inputs, LangError, run

# the inputs a reacting program is checked with: three presses and the knob turned up in steps
PROBE = Inputs(presses=[(300, 500), (900, 1000), (1500, 1900)], knob=[(0, 10), (800, 60), (1600, 95)],
               distance=[(0, 120), (600, 15), (900, 60), (1500, 10), (1800, 90)],
               line=[(0, 0), (300, 1), (600, 0), (900, 2), (1200, 3), (1500, 0)],
               tilt=[(0, 0), (1000, 45), (1300, 0)], shakes=[700, 1600],
               temp=[(0, 24), (1000, 19)], humidity=[(0, 40), (1200, 75)],
               sound=[(0, 5), (500, 80), (700, 5), (1400, 90), (1600, 5)], behind=[(0, 100), (1000, 15), (1500, 100)])
SENSES = ("button()", "knob()", "distance()", "track()", "tilt()", "shaken()", "temp()", "humidity()", "sound()",
          "behind()")


def reacts(prog):
    """A program that runs until the next request (a `while 1:` loop) or waits for input."""
    return "while 1:" in prog or any(x in prog for x in SENSES)

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / "data" / "oled" / "pairs.jsonl"

WORDS = ["hello", "hi", "yes", "no", "ok", "go", "stop", "cat", "dog", "sun", "moon", "love", "code", "wow",
         "hello world", "good morning", "good night", "welcome", "ready", "done", "error", "loading", "boom",
         "on", "off", "play", "pause", "win", "lose", "home", "coffee", "tea", "matchbox", "esp32", "kate"]
NUMWORD = {1: "one", 2: "two", 3: "three", 4: "four", 5: "five", 6: "six", 7: "seven", 8: "eight", 9: "nine",
           10: "ten"}
SPEED = [("quickly", 100), ("fast", 150), ("", 300), ("slowly", 600), ("very slowly", 1000)]
VAR = ["i", "n", "k", "x"]
# everyday words and phrases: these also turn up in requests as filler ("can you", "thank you"), so the model has
# to see them as things to write, too
COMMON = ("you me we it is am are be do can will thanks thank please sorry happy sad hungry tired busy free open "
          "closed back soon later today tonight tomorrow now here there yes nope maybe sure cool nice great super best "
          "love hug kiss party cake food lunch dinner breakfast pizza beer wine water milk work school home office "
          "meeting call me baby mom dad kids friend team boss name time day week year birthday luck night morning "
          "evening hey hello bye goodbye ciao ahoj hola welcome congrats bravo oops help danger warning alarm fire ice "
          "hot cold warm rain snow wind sunny cloudy north south east west left right up down start end next back menu "
          "score level game over winner player one two three four five six seven eight nine ten zero "
          "inside outside prompt code coding model tiny small little chip board screen runs run here this that "
          "I my your our").split()
PHRASES = ["thank you", "good luck", "happy birthday", "see you", "see you soon", "love you", "miss you", "i love you",
           "well done", "good job", "nice day", "have fun", "be right back", "do not disturb", "game over",
           "happy new year", "merry christmas", "get well soon", "on my way", "you win", "you lose", "try again",
           "time for tea", "back in 5", "lunch time", "coffee break", "no signal", "low battery", "out of order",
           "come in", "keep out", "be quiet", "hello there", "good evening", "good afternoon", "sweet dreams",
           "all good", "not now", "call me", "wake up", "go home", "let's go", "level up", "high score", "press start",
           "you prompt", "I code", "inside", "tiny chip", "inside a tiny chip", "I code inside", "runs inside", "in a chip",
           "tiny coding model", "right here", "on this chip"]
DICT = Path("/usr/share/dict/words")   # any word list; the model must learn to copy words, not remember them
# shapes the language can draw; anything else asked to be drawn gets an honest "?"
KNOWN = {"circle", "ring", "rings", "square", "box", "rectangle", "frame", "border", "line", "lines", "dot", "dots",
         "ball", "grid", "smiley", "face", "target", "triangle", "heart", "house", "sun", "star", "arrow", "stripes",
         "checkerboard", "staircase", "stairs", "cross", "plus", "x", "bar", "outline", "spiral", "pattern", "cup",
         "mug"}
_dict = None


def dict_words():
    global _dict
    if _dict is None:
        try:
            ws = DICT.read_text(errors="ignore").split()
        except OSError:
            ws = []
        _dict = sorted({w for w in ws if re.fullmatch(r"[a-z]{3,9}", w)}) or WORDS
    return _dict


def word(r):
    """Something a person might want written: any word, two words, a name, a code, a number."""
    k = r.random()
    if k < 0.08:
        return pick(r, COMMON)
    if k < 0.14:
        return pick(r, PHRASES)
    if k < 0.18:
        return pick(r, COMMON) + " " + pick(r, COMMON + WORDS)
    if k < 0.2:
        return pick(r, WORDS)
    if k < 0.55:
        return pick(r, dict_words())
    if k < 0.7:
        return pick(r, dict_words()) + " " + pick(r, dict_words())
    if k < 0.78:
        return pick(r, dict_words()).capitalize()
    if k < 0.84:
        return pick(r, dict_words()).upper()
    if k < 0.92:
        return str(r.randint(0, 99999))
    return "".join(r.choice(string.ascii_lowercase + string.digits) for _ in range(r.randint(2, 8)))


def unknown(r):
    while True:
        w = pick(r, dict_words())
        if w not in KNOWN and w.rstrip("s") not in KNOWN:
            return w


def a(w):
    return ("an " if w[0] in "aeiou" else "a ") + w


def spot(r, R):
    """Where a shape of radius R goes: (phrase, x, y), kept on the screen."""
    ph, x, y = pick(r, [("", 64, 32), ("", 64, 32), ("in the middle", 64, 32), ("in the center", 64, 32),
                        ("in the centre", 64, 32), ("on the left", 32, 32), ("on the right", 96, 32),
                        ("in the corner", 0, 0), ("in the top left corner", 0, 0), ("in the top right corner", 127, 0),
                        ("in the bottom left corner", 0, 63), ("in the bottom right corner", 127, 63),
                        ("at the top", 64, 0), ("at the bottom", 64, 63)])
    x = min(max(x, R + 1), 126 - R)
    y = min(max(y, R + 1), 62 - R)
    return ph, x, y


def size(r, small, mid, big):
    return pick(r, [("", mid), ("", mid), ("small ", small), ("little ", small), ("tiny ", max(3, small // 2)),
                    ("big ", big), ("large ", big), ("huge ", big)])


def draw_verb(r):
    return pick(r, ["draw", "draw", "make", "show", "show me", "put", "display", "i want", "give me", "sketch", "paint"])


def pick(r, xs):
    return r.choice(xs)


def num(r, n):
    """A number as a person might type it."""
    return NUMWORD[n] if n in NUMWORD and r.random() < 0.4 else str(n)


def times(r, n):
    """How many times, as a person might say it."""
    if n == 2 and r.random() < 0.4:
        return "twice"
    if n == 3 and r.random() < 0.2:
        return "thrice"
    return f"{num(r, n)} times"


def cx(s):
    return max(0, (W - CW * len(s)) // 2)


def place(r):
    """A position for text: (phrase, x of a function of the string, y)."""
    return pick(r, [("in the middle", "mid", 28), ("in the center", "mid", 28), ("at the top", "mid", 0),
                    ("at the bottom", "mid", 56), ("in the top left corner", 0, 0), ("on the left", 0, 28),
                    ("", "mid", 28)])


def f_text(r):
    w = word(r)
    where, x, y = place(r)
    x = cx(w) if x == "mid" else x
    q = pick(r, ['"', "'", "", "", ""])
    the = pick(r, ["", "", "the word ", "the text "]) if " " not in w else pick(r, ["", "the text ", "the words "])
    verb = pick(r, ["write", "write", "show", "display", "print", "put", "type", "say", "show me", "i want to see",
                    "can you write", "let me see", "spell", "put up"])
    prompt = f"{verb} {the}{q}{w}{q}" + (f" {where}" if where else "") + pick(r, ["", "", " on the screen", " on the display"])
    if w.isdigit() and r.random() < 0.4:
        prompt = pick(r, [f"show the number {w}", f"write the number {w}", f"display the number {w}", f"the number {w}",
                          f"show {w}", f"put the number {w} on the screen"])
        x, y = cx(w), 28
    elif r.random() < 0.15:
        prompt = pick(r, [f"the screen should say {q}{w}{q}", f"{q}{w}{q} on the screen", f"make it say {q}{w}{q}",
                          f"just {q}{w}{q}", f"text: {w}"])
        x, y = cx(w), 28
    return prompt, f'clear()\ntext({x}, {y}, "{w}")\n'


def f_two_lines(r):
    a, b = word(r)[:21], word(r)[:21]
    q = pick(r, ['"', "'", "", "", ""])
    A, B = f"{q}{a}{q}", f"{q}{b}{q}"
    prompt = pick(r, [f"write {A} and under it {B}", f"show {A} on the first line and {B} on the second",
                      f"two lines: {A} and {B}", f"{A} on top and {B} below", f"write {A} with {B} under it",
                      f"top line {A}, bottom line {B}", f"put {A} above {B}", f"first {A} then below it {B}",
                      f"write {A} and {B} on two lines", f"{A} and under that {B}"])
    return prompt, f'clear()\ntext({cx(a)}, 20, "{a}")\ntext({cx(b)}, 36, "{b}")\n'


def f_count(r):
    up = r.random() < 0.5
    n = r.randint(3, 10)
    sp, ms = pick(r, SPEED)
    v = pick(r, VAR)
    end = r.random() < 0.4
    fin = pick(r, ["GO", "done", "boom", "end", "ready"]) if r.random() < 0.5 else word(r)
    if up:
        prompt = pick(r, [f"count from 1 to {num(r, n)}", f"count to {num(r, n)}", f"count up to {num(r, n)}",
                          f"show the numbers 1 to {num(r, n)} one by one", f"count one to {num(r, n)}",
                          f"numbers from 1 to {num(r, n)}, one after another"])
        rng = f"range(1, {n + 1})"
    else:
        prompt = pick(r, [f"count down from {num(r, n)}", f"countdown from {num(r, n)}", f"count down from {num(r, n)} to 1",
                          f"countdown {num(r, n)}", f"a countdown from {num(r, n)}", f"count backwards from {num(r, n)}",
                          f"do a countdown from {num(r, n)}"])
        rng = f"range({n}, 0, -1)"
    if sp:
        prompt += " " + sp
    if end:
        prompt += pick(r, [f" then show {fin}", f" and then write {fin}", f", then say {fin}", f" and then {fin}",
                           f" and end with {fin}", f", then {fin}", f" and finish with {fin}", f" then write {fin}"])
    prog = f"for {v} in {rng}:\n    clear()\n    text(60, 28, str({v}))\n    wait({ms})\n"
    if end and len(fin) <= 21 and r.random() < 0.3:
        prompt += pick(r, [" with a cup", " and a cup", " and draw a cup", " with a coffee cup", " and a mug", " with a mug"])
        prog += f'clear()\ntext({cx(fin)}, 4, "{fin}")\n' + cup(60, 42, 12)
    elif end:
        prog += f'clear()\ntext({cx(fin)}, 28, "{fin}")\n'
    return prompt, prog


def f_circle(r):
    sz, R = size(r, 8, 20, 28)
    rad = None
    if r.random() < 0.25:
        R = rad = r.randint(4, 30)
        sz = ""
    where, x, y = spot(r, R)
    noun = pick(r, ["circle", "circle", "ring", "round shape"])
    prompt = f"{draw_verb(r)} a {sz}{noun}" + (pick(r, [f" with radius {rad}", f" of radius {rad}", f", radius {rad}"]) if rad else "")
    prompt += (" " + where if where else "")
    return prompt, f"clear()\ncircle({x}, {y}, {R})\n"


def f_square(r):
    sz, R = size(r, 8, 16, 28)
    if r.random() < 0.2:
        R = r.randint(3, 30)
        sz = f"{2 * R} pixel "
    filled = r.random() < 0.35
    where, x, y = spot(r, R)
    noun = pick(r, ["square", "square", "box"])
    adj = pick(r, ["filled ", "solid ", "full "]) if filled else pick(r, ["", "", "empty ", "hollow "])
    prompt = f"{draw_verb(r)} a {sz}{adj}{noun}" + (" " + where if where else "")
    return prompt, f"clear()\n{'fill' if filled else 'rect'}({x - R}, {y - R}, {2 * R}, {2 * R})\n"


def tri(x, y, R):
    return f"line({x}, {y - R}, {x - R}, {y + R})\nline({x - R}, {y + R}, {x + R}, {y + R})\nline({x + R}, {y + R}, {x}, {y - R})\n"


def f_triangle(r):
    sz, R = size(r, 8, 18, 28)
    where, x, y = spot(r, R)
    return f"{draw_verb(r)} a {sz}triangle" + (" " + where if where else ""), "clear()\n" + tri(x, y, R)


def heart(x, y, s):
    return (f"circle({x - s}, {y - s // 2}, {s})\ncircle({x + s}, {y - s // 2}, {s})\n"
            f"line({x - 2 * s}, {y - s // 2}, {x}, {y + 2 * s})\nline({x + 2 * s}, {y - s // 2}, {x}, {y + 2 * s})\n")


def f_heart(r):
    sz, s = size(r, 5, 9, 13)
    where, x, y = spot(r, 2 * s)
    y = min(max(y, s + s // 2 + 1), 62 - 2 * s)
    noun = pick(r, ["heart", "heart", "love heart", "heart shape"])
    return f"{draw_verb(r)} a {sz}{noun}" + (" " + where if where else ""), "clear()\n" + heart(x, y, s)


def house(x, y, s):
    # body 2s wide, s tall, standing on y + s; roof up to y - s; a door
    return (f"rect({x - s}, {y}, {2 * s}, {s})\nline({x - s}, {y}, {x}, {y - s})\nline({x}, {y - s}, {x + s}, {y})\n"
            f"rect({x - s // 5}, {y + s // 2}, {max(2, s // 3)}, {s - s // 2})\n")


def f_house(r):
    sz, s = size(r, 10, 20, 30)
    where, x, y = spot(r, s)
    noun = pick(r, ["house", "house", "little house" if not sz else "house", "home", "hut"])
    return f"{draw_verb(r)} a {sz}{noun}" + (" " + where if where else ""), "clear()\n" + house(x, y, s)


def sun(x, y, R):
    out = f"circle({x}, {y}, {R})\n"
    for k in range(8):
        a_ = k * math.pi / 4
        c, s_ = math.cos(a_), math.sin(a_)
        out += f"line({x + round(c * (R + 3))}, {y + round(s_ * (R + 3))}, {x + round(c * (R + 9))}, {y + round(s_ * (R + 9))})\n"
    return out


def f_sun(r):
    sz, R = size(r, 5, 10, 14)
    where, x, y = spot(r, R + 9)
    noun = pick(r, ["sun", "sun", "shining sun", "sun with rays"])
    return f"{draw_verb(r)} a {sz}{noun}" + (" " + where if where else ""), "clear()\n" + sun(x, y, R)


def star(x, y, R):
    pts = [(x + round(R * math.sin(k * 4 * math.pi / 5)), y - round(R * math.cos(k * 4 * math.pi / 5))) for k in range(5)]
    return "".join(f"line({pts[k][0]}, {pts[k][1]}, {pts[(k + 1) % 5][0]}, {pts[(k + 1) % 5][1]})\n" for k in range(5))


def f_star(r):
    sz, R = size(r, 9, 20, 30)
    where, x, y = spot(r, R)
    return f"{draw_verb(r)} a {sz}star" + (" " + where if where else ""), "clear()\n" + star(x, y, R)


def cup(x, y, s):
    """A mug: body, handle on the right, two wisps of steam."""
    out = f"rect({x - s}, {y - s}, {2 * s}, {2 * s})\nrect({x + s - 1}, {y - s // 2}, {s // 2 + 2}, {s})\n"
    for sx in (x - s // 2, x + s // 2):
        out += f"line({sx}, {y - s - 3}, {sx + 2}, {y - s - 6})\nline({sx + 2}, {y - s - 6}, {sx}, {y - s - 9})\n"
    return out


def f_cup(r):
    sz, s = size(r, 8, 12, 16)
    where, x, y = spot(r, s + 4)
    y = min(max(y, s + 10), 63 - s)
    noun = pick(r, ["cup", "mug", "coffee cup", "cup of coffee", "cup of tea", "coffee mug", "hot drink"])
    return f"{draw_verb(r)} a {sz}{noun}" + (" " + where if where else ""), "clear()\n" + cup(x, y, s)


def f_arrow(r):
    d = pick(r, ["right", "left", "up", "down"])
    ph = pick(r, [f"draw an arrow pointing {d}", f"an arrow to the {d}" if d in ("left", "right") else f"an arrow pointing {d}",
                  f"show an arrow {d}", f"make a {d} arrow", f"point {d}", f"draw a {d} arrow"])
    prog = {"right": "line(20, 32, 108, 32)\nline(108, 32, 92, 20)\nline(108, 32, 92, 44)\n",
            "left": "line(20, 32, 108, 32)\nline(20, 32, 36, 20)\nline(20, 32, 36, 44)\n",
            "up": "line(64, 4, 64, 60)\nline(64, 4, 52, 18)\nline(64, 4, 76, 18)\n",
            "down": "line(64, 4, 64, 60)\nline(64, 60, 52, 46)\nline(64, 60, 76, 46)\n"}[d]
    return ph, "clear()\n" + prog


def f_fill_screen(r):
    return pick(r, ["fill the screen", "fill the whole screen", "make the screen all white", "turn on all the pixels",
                    "light up the whole screen", "fill the display", "make everything white", "all pixels on",
                    "paint the whole screen", "fill it all in", "light the screen up", "make the screen bright"]), \
        "clear()\nfill(0, 0, 128, 64)\n"


def f_clear_screen(r):
    return pick(r, ["clear the screen", "clear the display", "blank the screen", "erase everything", "wipe the screen",
                    "turn the screen off", "make the screen black", "clear it", "empty the screen", "clean the screen",
                    "nothing", "show nothing", "reset the screen", "all pixels off"]), "clear()\n"


def f_blink_screen(r):
    n = r.randint(2, 6)
    sp, ms = pick(r, SPEED)
    v = pick(r, VAR)
    prompt = pick(r, [f"blink the screen {times(r, n)}", f"flash the screen {times(r, n)}",
                      f"flash the display {times(r, n)}", f"make the screen blink {times(r, n)}",
                      "blink the screen", "flash the screen", "make the screen flash"])
    if not any(t in prompt for t in (" times", "twice", "thrice")):
        n = 3
    prompt += (" " + sp if sp else "")
    return prompt, f"for {v} in range({n}):\n    fill(0, 0, 128, 64)\n    wait({ms})\n    clear()\n    wait({ms})\n"


def f_row(r):
    n = r.randint(2, 6)
    v = pick(r, VAR)
    gap = W // (n + 1)
    R = min(gap // 2 - 2, 14)
    kind = pick(r, ["circles", "squares", "boxes", "rings", "triangles"])
    prompt = pick(r, [f"draw {num(r, n)} {kind} in a row", f"{num(r, n)} {kind} next to each other",
                      f"{num(r, n)} {kind} side by side", f"put {num(r, n)} {kind} in a line", f"{num(r, n)} {kind}",
                      f"draw {num(r, n)} {kind}", f"show {num(r, n)} {kind}"])
    if kind in ("circles", "rings"):
        body = f"    circle({gap} + {v} * {gap}, 32, {R})\n"
    elif kind == "triangles":
        body = (f"    x = {gap} + {v} * {gap}\n    line(x, {32 - R}, x - {R}, {32 + R})\n    line(x - {R}, {32 + R}, x + {R}, {32 + R})\n"
                f"    line(x + {R}, {32 + R}, x, {32 - R})\n")
    else:
        body = f"    rect({gap} + {v} * {gap} - {R}, {32 - R}, {2 * R}, {2 * R})\n"
    return prompt, f"clear()\nfor {v} in range({n}):\n{body}"


def f_unknown(r):
    w = unknown(r)
    prompt = pick(r, [f"draw {a(w)}", f"draw me {a(w)}", f"make a picture of {a(w)}", f"a picture of {a(w)}",
                      f"can you draw {a(w)}", f"paint {a(w)}", f"sketch {a(w)}", f"draw a {w}", f"show me a picture of {w}",
                      f"draw some {w}", f"i want a drawing of {a(w)}"])
    return prompt, 'clear()\ntext(61, 28, "?")\n'


def f_frame(r):
    base = pick(r, ["draw a frame around the screen", "draw a border", "make a box around the edge",
                    "draw a rectangle around the whole screen", "border around the screen", "frame the screen",
                    "draw an outline around the display", "put a border on the screen"])
    kind = pick(r, ["plain", "plain", "double", "inset", "thick"])
    if kind == "plain":
        return base, f"clear()\nrect(0, 0, {W}, {H})\n"
    if kind == "double":
        return base.replace("a frame", "a double frame").replace("a border", "a double border") + ("" if "double" in base else " twice"), \
            f"clear()\nrect(0, 0, {W}, {H})\nrect(3, 3, {W - 6}, {H - 6})\n"
    if kind == "inset":
        g = r.randint(2, 10)
        return base + f" {g} pixels from the edge", f"clear()\nrect({g}, {g}, {W - 2 * g}, {H - 2 * g})\n"
    t = r.randint(2, 4)
    return base + f" {t} pixels thick", f"clear()\nfor i in range({t}):\n    rect(i, i, {W} - 2 * i, {H} - 2 * i)\n"


def f_box(r):
    w, h = r.randint(10, 60), r.randint(8, 40)
    filled = r.random() < 0.4
    prompt = pick(r, ["draw", "make"]) + (" a filled" if filled else " a") + pick(r, [f" box {w} by {h}", f" rectangle {w} wide and {h} tall"])
    centered = r.random() < 0.6
    x, y = ((W - w) // 2, (H - h) // 2) if centered else (0, 0)
    prompt += " in the middle" if centered else " in the corner"
    return prompt, f"clear()\n{'fill' if filled else 'rect'}({x}, {y}, {w}, {h})\n"


def f_lines(r):
    kind = pick(r, ["diagonal", "cross", "x", "horizontal", "vertical"])
    if kind == "diagonal":
        return pick(r, ["draw a diagonal line", "draw a line from the top left to the bottom right"]), "clear()\nline(0, 0, 127, 63)\n"
    if kind == "x":
        return pick(r, ["draw an X", "draw a big X across the screen", "cross out the screen"]), "clear()\nline(0, 0, 127, 63)\nline(0, 63, 127, 0)\n"
    if kind == "cross":
        return pick(r, ["draw a plus in the middle", "draw a cross in the center"]), "clear()\nline(64, 0, 64, 63)\nline(0, 32, 127, 32)\n"
    n = r.randint(2, 8)
    v = pick(r, VAR)
    if kind == "horizontal":
        gap = H // (n + 1)
        return (pick(r, [f"draw {num(r, n)} horizontal lines", f"{num(r, n)} lines across the screen"]),
                f"clear()\nfor {v} in range({n}):\n    y = {gap} + {v} * {gap}\n    line(0, y, 127, y)\n")
    gap = W // (n + 1)
    return (pick(r, [f"draw {num(r, n)} vertical lines", f"{num(r, n)} lines from top to bottom"]),
            f"clear()\nfor {v} in range({n}):\n    x = {gap} + {v} * {gap}\n    line(x, 0, x, 63)\n")


def f_stripes(r):
    n = pick(r, [4, 8, 16])
    v = pick(r, VAR)
    if r.random() < 0.5:
        prompt = pick(r, ["draw vertical stripes", f"draw {num(r, n)} vertical stripes" if n <= 10 else "draw thin vertical stripes"])
        w = W // n
        return prompt, f"clear()\nfor {v} in range(0, {n}, 2):\n    fill({v} * {w}, 0, {w}, 64)\n"
    prompt = pick(r, ["draw horizontal stripes", f"draw {num(r, n)} horizontal stripes" if n <= 10 else "draw thin horizontal stripes"])
    h = H // n
    return prompt, f"clear()\nfor {v} in range(0, {n}, 2):\n    fill(0, {v} * {h}, 128, {h})\n"


def f_grid(r):
    step = pick(r, [8, 16, 32])
    prompt = pick(r, [f"draw a grid every {step} pixels", f"draw a grid with {step} pixel squares",
                      f"draw graph paper with {step} pixel squares", "draw a grid", "draw graph paper"])
    if "pixel" not in prompt:
        step = 16
    return prompt, (f"clear()\nfor x in range(0, 128, {step}):\n    line(x, 0, x, 63)\n"
                    f"for y in range(0, 64, {step}):\n    line(0, y, 127, y)\n")


def f_rings(r):
    n = r.randint(2, 6)
    v = pick(r, VAR)
    prompt = pick(r, [f"draw {num(r, n)} circles inside each other", f"{num(r, n)} rings in the middle", f"draw a target with {num(r, n)} rings",
                      "draw a target", "make a target", "a bullseye", "draw circles inside each other", "concentric circles"])
    if not any(c.isdigit() for c in prompt) and not any(t in prompt for t in NUMWORD.values()):
        n = 3
    step = 30 // n
    return prompt, f"clear()\nfor {v} in range(1, {n + 1}):\n    circle(64, 32, {v} * {step})\n"


def f_dots(r):
    n = r.randint(3, 12)
    v = pick(r, VAR)
    gap = W // (n + 1)
    prompt = pick(r, [f"draw {num(r, n)} dots in a row", f"put {num(r, n)} dots across the middle"])
    return prompt, f"clear()\nfor {v} in range({n}):\n    fill({gap} + {v} * {gap} - 1, 31, 3, 3)\n"


def f_smiley(r):
    sz, R = pick(r, [("", 24), ("", 24), ("small ", 14), ("little ", 14), ("tiny ", 10), ("big ", 30)])
    where, c, yc = spot(r, R)
    sad = r.random() < 0.25
    face = pick(r, ["sad face", "sad smiley", "frowning face"]) if sad else pick(r, ["smiley", "smiley face", "happy face", "face", "smile", "smiling face"])
    prompt = f"{draw_verb(r)} a {sz}{face}" + (" " + where if where else "")
    e = R * 2 // 5
    m = R // 2
    prog = f"clear()\ncircle({c}, {yc}, {R})\nfill({c - e - 2}, {yc - e}, 4, 4)\nfill({c + e - 2}, {yc - e}, 4, 4)\n"
    if sad:
        prog += f"line({c - m}, {yc + m + 4}, {c - m + 4}, {yc + m})\nline({c - m + 4}, {yc + m}, {c + m - 4}, {yc + m})\nline({c + m - 4}, {yc + m}, {c + m}, {yc + m + 4})\n"
    else:
        prog += f"line({c - m}, {yc + m}, {c - m + 4}, {yc + m + 4})\nline({c - m + 4}, {yc + m + 4}, {c + m - 4}, {yc + m + 4})\nline({c + m - 4}, {yc + m + 4}, {c + m}, {yc + m})\n"
    return prompt, prog


def f_move(r):
    sp, ms = pick(r, SPEED[:3])
    ms = max(30, ms // 3)
    v = pick(r, VAR)
    what = pick(r, [("dot", "fill({v}, 30, 4, 4)"), ("ball", "circle({v}, 32, 4)"), ("square", "fill({v}, 26, 12, 12)")])
    direction = pick(r, ["left to right", "right to left"])
    rng = "range(0, 124, 4)" if direction == "left to right" else "range(124, 0, -4)"
    to = direction.split()[-1]
    prompt = pick(r, [f"move a {what[0]} from {direction}", f"animate a {what[0]} going from {direction}",
                      f"a {what[0]} that slides from {direction}", f"a {what[0]} moving to the {to}",
                      f"move a {what[0]} to the {to}", f"a {what[0]} going {to}", f"slide a {what[0]} to the {to}",
                      f"make a {what[0]} move {to}", f"a moving {what[0]} going {to}"]) + (" " + sp if sp else "")
    return prompt, f"for {v} in {rng}:\n    clear()\n    {what[1].format(v=v)}\n    wait({ms})\n"


def f_bounce(r):
    n = r.randint(2, 5)
    size = pick(r, [("", 4), ("small ", 2), ("big ", 8)])
    sp, ms = pick(r, SPEED)
    step = {100: 8, 150: 6, 300: 4, 600: 2, 1000: 1}[ms]
    prompt = pick(r, [f"bounce a {size[0]}ball", f"bounce a {size[0]}ball {times(r, n)}", f"a bouncing {size[0]}ball",
                      f"animate a bouncing {size[0]}ball", f"a {size[0]}ball that bounces", f"bouncing {size[0]}ball",
                      f"a {size[0]}ball bouncing left and right", f"a {size[0]}ball bouncing between the walls {times(r, n)}"])
    if not any(t in prompt for t in (" times", "twice", "thrice")):
        n = 3
    prompt += (" " + sp if sp else "")
    R = size[1]
    return prompt, (f"x = {R}\nd = {step}\nhits = 0\nwhile hits < {n * 2}:\n    clear()\n    circle(x, 32, {R})\n    wait(30)\n"
                    f"    x = x + d\n    if x > {127 - R} or x < {R}:\n        d = -d\n        hits = hits + 1\n")


def f_grow(r):
    v = pick(r, VAR)
    shrink = r.random() < 0.3
    top = r.randint(10, 30)
    sp, ms = pick(r, SPEED)
    ms = max(30, ms // 4)
    if shrink:
        prompt = pick(r, ["shrink a circle", "a circle that gets smaller", "make a circle shrink to the middle"])
        rng = f"range({top}, 0, -2)"
    else:
        prompt = pick(r, ["grow a circle", "a circle that gets bigger", "make a circle grow from the middle", "animate a growing circle"])
        rng = f"range(1, {top + 1}, 2)"
    if r.random() < 0.5:
        prompt += pick(r, [f" up to radius {top}", f" to size {top}"]) if not shrink else f" from radius {top}"
    else:
        rng = "range(1, 31, 2)" if not shrink else "range(30, 0, -2)"
    prompt += (" " + sp if sp else "")
    return prompt, f"for {v} in {rng}:\n    clear()\n    circle(64, 32, {v})\n    wait({ms})\n"


def f_blink(r):
    w = word(r)[:21]
    n = r.randint(2, 6)
    sp, ms = pick(r, SPEED)
    v = pick(r, VAR)
    q = pick(r, ['"', "'", "", "", ""])
    W_ = f"{q}{w}{q}"
    prompt = pick(r, [f"blink {W_} {times(r, n)}", f"flash {W_} {times(r, n)}", f"make {W_} blink {times(r, n)}",
                      f"make the word {W_} blink {times(r, n)}", f"blink the text {W_} {times(r, n)}",
                      f"flash the word {W_} {times(r, n)}", f"write {W_} and blink it {times(r, n)}",
                      f"{W_} blinking {times(r, n)}"]) + (" " + sp if sp else "")
    return prompt, f'for {v} in range({n}):\n    clear()\n    text({cx(w)}, 28, "{w}")\n    wait({ms})\n    clear()\n    wait({ms})\n'


def f_progress(r):
    sp, ms = pick(r, SPEED[:4])
    ms = max(20, ms // 5)
    v = pick(r, VAR)
    label = r.random() < 0.4
    prompt = pick(r, ["fill a progress bar", "show a loading bar", "draw a progress bar that fills up"]) + (" " + sp if sp else "")
    prog = "clear()\n" + ('text(40, 20, "loading")\n' if label else "") + "rect(4, 28, 120, 10)\n"
    if label:
        prompt += pick(r, [" with the word loading", " and write loading above it"])
    prog += f"for {v} in range(0, 117, 4):\n    fill(6, 30, {v}, 6)\n    wait({ms})\n"
    return prompt, prog


def f_scroll(r):
    w = word(r)
    v = pick(r, VAR)
    prompt = pick(r, [f"scroll {w} across the screen", f"make {w} move from right to left", f"slide {w} across",
                      f"scroll the text {w}", f"scrolling text {w}", f"{w} scrolling across", f"let {w} run across the screen"])
    return prompt, f'for {v} in range(128, -{CW * len(w)}, -4):\n    clear()\n    text({v}, 28, "{w}")\n    wait(40)\n'


def f_boxed_word(r):
    w = word(r)[:19]
    x = cx(w)
    prompt = pick(r, [f"write {w} in a box", f"write {w} and draw a box around it", f"{w} with a frame around it",
                      f"draw a box around {w}", f"put {w} in a box", f"{w} in a frame", f"a box with {w} inside"])
    return prompt, f'clear()\ntext({x}, 28, "{w}")\nrect({x - 4}, 24, {CW * len(w) + 7}, 16)\n'


def f_circle_word(r):
    w = word(r)[:21]
    prompt = pick(r, [f"draw a circle and write {w} under it", f"a circle with {w} below it"])
    return prompt, f'clear()\ncircle(64, 22, 16)\ntext({cx(w)}, 48, "{w}")\n'


def f_count_then_shape(r):
    n = r.randint(3, 5)
    shape = pick(r, [("a circle", "circle(64, 32, 20)"), ("a smiley", "circle(64, 32, 24)\nfill(54, 22, 4, 4)\nfill(70, 22, 4, 4)\nline(54, 42, 58, 46)\nline(58, 46, 70, 46)\nline(70, 46, 74, 42)"),
                         ("an X", "line(0, 0, 127, 63)\nline(0, 63, 127, 0)")])
    prompt = pick(r, [f"count down from {num(r, n)} and then draw {shape[0]}", f"countdown from {num(r, n)}, then show {shape[0]}"])
    return prompt, f"for i in range({n}, 0, -1):\n    clear()\n    text(60, 28, str(i))\n    wait(500)\nclear()\n{shape[1]}\n"


def f_numbers_list(r):
    n = r.randint(3, 8)
    v = pick(r, VAR)
    prompt = pick(r, [f"write the numbers 1 to {n} in a column", f"list the numbers from 1 to {num(r, n)} down the screen"])
    return prompt, f"clear()\nfor {v} in range(1, {n + 1}):\n    text(0, ({v} - 1) * 8, str({v}))\n"


def f_squares(r):
    n = r.randint(3, 8)
    v = pick(r, VAR)
    prompt = pick(r, [f"write the squares of 1 to {n}", f"show {num(r, n)} square numbers"])
    return prompt, f'clear()\nfor {v} in range(1, {n + 1}):\n    text(0, ({v} - 1) * 8, str({v}) + " x " + str({v}) + " = " + str({v} * {v}))\n'


def f_even_numbers(r):
    n = r.randint(10, 20)
    v = pick(r, VAR)
    which = pick(r, ["even", "odd"])
    rem = 0 if which == "even" else 1
    prompt = pick(r, [f"show the {which} numbers up to {n}", f"write all {which} numbers from 1 to {n}"])
    return prompt, (f'clear()\nline_text = ""\nfor {v} in range(1, {n + 1}):\n    if {v} % 2 == {rem}:\n'
                    f'        line_text = line_text + str({v}) + " "\ntext(0, 28, line_text)\n')


def f_staircase(r):
    n = r.randint(3, 7)
    v = pick(r, VAR)
    s = 64 // n
    prompt = pick(r, [f"draw a staircase with {num(r, n)} steps", f"{num(r, n)} stairs going up"])
    return prompt, f"clear()\nfor {v} in range({n}):\n    fill({v} * {s * 2}, 64 - ({v} + 1) * {s}, {s * 2}, ({v} + 1) * {s})\n"


def f_checker(r):
    size = pick(r, [(4, "small"), (8, ""), (16, "big")])
    base = pick(r, ["draw a checkerboard", "draw a chess board pattern", "checker pattern", "make a checkerboard",
                    "fill the screen with a checker pattern", "draw black and white squares like a chess board"])
    prompt = base + (f" with {size[1]} squares" if size[1] else "")
    if r.random() < 0.3:
        prompt = base + f" with squares of {size[0]} pixels"
    q = size[0]
    return prompt, (f"clear()\nfor y in range(0, 64, {q}):\n    for x in range(0, 128, {q}):\n"
                    f"        if (x // {q} + y // {q}) % 2 == 0:\n            fill(x, y, {q}, {q})\n")



# ---------------------------------------------------------------- hardware: LED, colour LED, buzzer, button, knob
COLOURS = {"red": (255, 0, 0), "green": (0, 255, 0), "blue": (0, 0, 255), "yellow": (255, 180, 0),
           "orange": (255, 80, 0), "purple": (160, 0, 255), "pink": (255, 60, 120), "white": (255, 255, 255),
           "cyan": (0, 255, 255), "magenta": (255, 0, 255)}
LED = ["the LED", "the led", "the light", "the lamp", "LED", "the little light"]
RGBN = ["the colour LED", "the color LED", "the RGB LED", "the light", "the colour light", "the color light"]
BTN = ["the button", "the button", "button"]
KNOB = ["the knob", "the knob", "the dial", "the potentiometer", "the pot"]
POLL = 20


def f_led_blink(r):
    n = r.randint(1, 8)
    sp, ms = pick(r, SPEED)
    v = pick(r, VAR)
    what = pick(r, LED)
    prompt = pick(r, [f"blink {what} {times(r, n)}", f"flash {what} {times(r, n)}", f"make {what} blink {times(r, n)}",
                      f"turn {what} on and off {times(r, n)}"]) + (" " + sp if sp else "")
    return prompt, f"for {v} in range({n}):\n    led(1)\n    wait({ms})\n    led(0)\n    wait({ms})\n"


def f_led_set(r):
    on = r.random() < 0.6
    what = pick(r, LED)
    if on:
        prompt = pick(r, [f"turn on {what}", f"switch on {what}", f"turn {what} on", f"light up {what}", f"{what} on"])
    else:
        prompt = pick(r, [f"turn off {what}", f"switch off {what}", f"turn {what} off", f"{what} off"])
    return prompt, f"led({1 if on else 0})\n"


def f_led_hold(r):
    what, b = pick(r, LED), pick(r, BTN)
    prompt = pick(r, [f"light {what} while I hold {b}", f"turn on {what} while {b} is pressed",
                      f"{what} on when I press {b}", f"make {what} follow {b}", f"press {b} to light {what}"])
    return prompt, f"while 1:\n    led(button())\n    wait({POLL})\n"


def f_led_toggle(r):
    what, b = pick(r, LED), pick(r, BTN)
    prompt = pick(r, [f"toggle {what} when I press {b}", f"press {b} to switch {what} on and off",
                      f"{b} toggles {what}", f"each press of {b} switches {what}"])
    return prompt, (f"on = 0\nprev = 0\nwhile 1:\n    b = button()\n    if b and not prev:\n        on = 1 - on\n"
                    f"        led(on)\n    prev = b\n    wait({POLL})\n")


def f_count_presses(r):
    b = pick(r, BTN)
    prompt = pick(r, [f"count how many times I press {b}", f"show the number of {b} presses",
                      f"count {b} presses on the screen", f"a counter for {b}", f"count the presses of {b}"])
    return prompt, (f'n = 0\nprev = 0\nclear()\ntext(61, 28, "0")\nwhile 1:\n    b = button()\n    if b and not prev:\n'
                    f'        n = n + 1\n        clear()\n        text(61, 28, str(n))\n    prev = b\n    wait({POLL})\n')


def f_beep(r):
    n = r.randint(1, 6)
    sp, ms = pick(r, SPEED)
    v = pick(r, VAR)
    prompt = pick(r, [f"beep {times(r, n)}", f"make the buzzer beep {times(r, n)}", f"buzz {times(r, n)}",
                      f"sound the buzzer {times(r, n)}"]) + (" " + sp if sp else "")
    return prompt, f"for {v} in range({n}):\n    beep({ms})\n    wait({ms})\n"


def f_beep_press(r):
    b = pick(r, BTN)
    prompt = pick(r, [f"beep when I press {b}", f"buzz every time I press {b}", f"make {b} beep",
                      f"beep while {b} is pressed"])
    return prompt, f"while 1:\n    if button():\n        beep(100)\n    wait({POLL})\n"


def f_blink_beep(r):
    n = r.randint(2, 6)
    v = pick(r, VAR)
    prompt = pick(r, [f"blink and beep {times(r, n)}", f"flash the LED and beep {times(r, n)}",
                      f"beep and blink {times(r, n)}"])
    return prompt, f"for {v} in range({n}):\n    led(1)\n    beep(200)\n    led(0)\n    wait(200)\n"


def f_knob_bar(r):
    k = pick(r, KNOB)
    prompt = pick(r, [f"show {k} as a bar", f"a bar that follows {k}", f"draw a bar for {k}", f"{k} position as a bar",
                      f"show how far {k} is turned"])
    return prompt, f"while 1:\n    clear()\n    rect(0, 28, 128, 8)\n    fill(0, 28, knob() * 128 // 100, 8)\n    wait(50)\n"


def f_knob_number(r):
    k = pick(r, KNOB)
    prompt = pick(r, [f"show the value of {k}", f"show {k} as a number", f"write {k} position on the screen",
                      f"display {k}", f"what is {k} at"])
    return prompt, "while 1:\n    clear()\n    text(55, 28, str(knob()))\n    wait(100)\n"


def f_knob_circle(r):
    k = pick(r, KNOB)
    prompt = pick(r, [f"a circle that grows with {k}", f"{k} sets the size of a circle", f"turn {k} to resize a circle"])
    return prompt, "while 1:\n    clear()\n    circle(64, 32, knob() * 30 // 100 + 1)\n    wait(50)\n"


def f_knob_speed(r):
    k, what = pick(r, KNOB), pick(r, LED)
    prompt = pick(r, [f"blink {what}, {k} sets the speed", f"{k} controls how fast {what} blinks",
                      f"blink {what} faster when I turn {k} up"])
    return prompt, "while 1:\n    led(1)\n    wait(1050 - knob() * 10)\n    led(0)\n    wait(1050 - knob() * 10)\n"


def f_rgb(r):
    name = pick(r, list(COLOURS))
    c = COLOURS[name]
    what = pick(r, RGBN)
    prompt = pick(r, [f"make {what} {name}", f"turn {what} {name}", f"{name} light", f"set {what} to {name}",
                      f"light {what} {name}", f"show {name} on {what}"])
    return prompt, f"rgb({c[0]}, {c[1]}, {c[2]})\n"


def f_rgb_off(r):
    what = pick(r, [w for w in RGBN if w != "the light"])   # "the light" alone is the plain LED
    return pick(r, [f"turn {what} off", f"switch off {what}", f"{what} off"]), "rgb(0, 0, 0)\n"


def f_rgb_cycle(r):
    names = r.sample(list(COLOURS)[:7], r.randint(2, 4))
    n = r.randint(1, 4)
    sp, ms = pick(r, SPEED)
    v = pick(r, VAR)
    listed = ", ".join(names[:-1]) + " and " + names[-1]
    prompt = pick(r, [f"cycle through {listed} {times(r, n)}", f"show {listed} one after another {times(r, n)}",
                      f"flash {listed} {times(r, n)}"]) + (" " + sp if sp else "")
    body = "".join(f"    rgb({COLOURS[c][0]}, {COLOURS[c][1]}, {COLOURS[c][2]})\n    wait({ms})\n" for c in names)
    return prompt, f"for {v} in range({n}):\n{body}rgb(0, 0, 0)\n"


def f_traffic(r):
    prompt = pick(r, ["traffic light", "make a traffic light", "run a traffic light", "be a traffic light",
                      "red, yellow, green like a traffic light"])
    return prompt, ("while 1:\n    rgb(255, 0, 0)\n    wait(2000)\n    rgb(255, 180, 0)\n    wait(600)\n"
                    "    rgb(0, 255, 0)\n    wait(2000)\n    rgb(255, 180, 0)\n    wait(600)\n")


def f_press_show(r):
    w = word(r)[:21]
    b = pick(r, BTN)
    prompt = pick(r, [f"when I press {b}, write {w}", f"show {w} when {b} is pressed", f"press {b} to show {w}",
                      f"write {w} while I hold {b}"])
    hold = "while I hold" in prompt
    if hold:
        return prompt, (f'while 1:\n    clear()\n    if button():\n        text({cx(w)}, 28, "{w}")\n    wait({POLL})\n')
    return prompt, (f'clear()\nwhile button() == 0:\n    wait({POLL})\ntext({cx(w)}, 28, "{w}")\n')


def f_press_countdown(r):
    n = r.randint(3, 10)
    b = pick(r, BTN)
    prompt = pick(r, [f"press {b} to start a countdown from {num(r, n)}", f"when I press {b}, count down from {num(r, n)}",
                      f"wait for {b}, then count down from {num(r, n)}"])
    return prompt, (f'clear()\nwhile button() == 0:\n    wait({POLL})\nfor i in range({n}, 0, -1):\n    clear()\n'
                    f'    text(60, 28, str(i))\n    wait(500)\nclear()\ntext(55, 28, "GO")\n')


def f_sos(r):
    what = pick(r, LED)
    prompt = pick(r, [f"blink SOS with {what}", f"SOS in morse code on {what}", "blink SOS", "flash SOS",
                      "beep SOS" if r.random() < 0.5 else "send SOS"])
    if prompt == "beep SOS":
        dot, dash = "    beep(150)\n    wait(150)\n", "    beep(450)\n    wait(150)\n"
    else:
        dot, dash = "    led(1)\n    wait(150)\n    led(0)\n    wait(150)\n", "    led(1)\n    wait(450)\n    led(0)\n    wait(150)\n"
    return prompt, ("for i in range(3):\n" + dot + "for i in range(3):\n" + dash + "for i in range(3):\n" + dot)


HW_FAMILIES = [f_led_blink, f_led_set, f_led_hold, f_led_toggle, f_count_presses, f_beep, f_beep_press, f_blink_beep,
               f_knob_bar, f_knob_number, f_knob_circle, f_knob_speed, f_rgb, f_rgb_off, f_rgb_cycle, f_traffic,
               f_press_show, f_press_countdown, f_sos]


# ---------------------------------------------------------------- the car: four normal wheels (two L9110S, so it
# drives and turns but never slides sideways: move(f, 0, r)), a head on a servo with a distance sensor, line sensors,
# accelerometer, temperature and humidity, the screen as its face, a buzzer as its horn, and the 8x8 NeoPixel as its
# lights (rgb). People talk to it casually, so requests come with "yo", "pls", "lol" and slang for the same moves.
# Times are at speed 60; a 90 degree turn is 700 ms.
CAR = ["", "", "the car", "the robot", "yourself"]
SPEEDS = [("", 60), ("", 60), ("slowly", 30), ("fast", 90), ("very slowly", 20), ("quickly", 90),
          ("nice and slow", 30), ("super fast", 90), ("like a snail", 20), ("full speed", 100), ("at full speed", 100),
          ("gently", 30), ("real slow", 20), ("really fast", 90)]
# speed is a scale, not three words: graded words all the way from a crawl to flat out, and numbers, so the model
# has an ordered "how fast" to write from (and the steering knob something to move along)
SPEED_SCALE = [("at a crawl", 10), ("barely moving", 10), ("super slowly", 15), ("like a snail", 20),
               ("very slowly", 20), ("real slow", 20), ("slowly", 30), ("nice and slow", 30), ("gently", 30),
               ("carefully", 35), ("a bit slow", 40), ("slowish", 40), ("not too fast", 45), ("at a relaxed pace", 45),
               ("at medium speed", 50), ("at half speed", 50), ("at normal speed", 60), ("a bit fast", 70),
               ("briskly", 70), ("pretty fast", 75), ("fast", 90), ("quickly", 90), ("really fast", 90),
               ("very fast", 95), ("super fast", 90), ("full speed", 100), ("at full speed", 100), ("flat out", 100),
               ("as fast as you can", 100)]


def spd(r, plain=0.35):
    """(phrase, speed): often nothing (60), else a graded word, or a number the way people say one."""
    k = r.random()
    if k < plain:
        return "", 60
    if k < plain + (1 - plain) * 0.7:
        return pick(r, SPEED_SCALE)
    n = r.randrange(10, 101, 5)
    return pick(r, [f"at speed {n}", f"speed {n}", f"at {n} percent", f"at {n}%", f"{n} percent speed",
                    f"at power {n}"]), n
TURN90 = 700


def secs(r):
    n = r.choice([1, 1, 2, 2, 3, 4, 5])
    return pick(r, [(f"{num(r, n)} seconds" if n > 1 else "1 second", n * 1000),
                    (f"for {num(r, n)} seconds" if n > 1 else "for a second", n * 1000),
                    (f"for {n} sec" if n > 1 else "for a sec", n * 1000), (f"{n}s", n * 1000)])


