# ---- the car's own small talk, its lights and horn, chained moves, and reacting to what its sensors read
def face(c=64, yc=32, R=24, sad=False):
    e, m = R * 2 // 5, R // 2
    out = f"circle({c}, {yc}, {R})\nfill({c - e - 2}, {yc - e}, 4, 4)\nfill({c + e - 2}, {yc - e}, 4, 4)\n"
    if sad:
        return out + (f"line({c - m}, {yc + m + 4}, {c - m + 4}, {yc + m})\nline({c - m + 4}, {yc + m}, {c + m - 4}, {yc + m})\n"
                      f"line({c + m - 4}, {yc + m}, {c + m}, {yc + m + 4})\n")
    return out + (f"line({c - m}, {yc + m}, {c - m + 4}, {yc + m + 4})\nline({c - m + 4}, {yc + m + 4}, {c + m - 4}, {yc + m + 4})\n"
                  f"line({c + m - 4}, {yc + m + 4}, {c + m}, {yc + m})\n")


def say(w, y=28):
    return f'clear()\ntext({cx(w)}, {y}, "{w}")\n'


