def c_chat(r):
    k = r.randrange(len(CHAT))
    phrases, prog = CHAT[k]
    return pick(r, phrases), prog(r)


LIGHTS = ["your lights", "the lights", "the leds", "your leds", "your headlights"]


def c_lights(r):
    kind = pick(r, ["colour", "colour", "colour", "off", "on", "police", "hazard", "rainbow"])
    if kind == "colour":
        name = pick(r, list(COLOURS))
        c = COLOURS[name]
        if r.random() < 0.3:                      # the lights are its eyes
            return pick(r, [f"make your eyes {name}", f"{name} eyes", f"{name} eyes please", f"turn your eyes {name}",
                            f"give me {name} eyes", f"eyes {name}", f"i want {name} eyes"]), f"rgb({c[0]}, {c[1]}, {c[2]})\n"
        prompt = pick(r, [f"turn {pick(r, LIGHTS)} {name}", f"make {pick(r, LIGHTS)} {name}", f"lights {name}",
                          f"glow {name}", f"go {name}", f"{name} lights", f"set {pick(r, LIGHTS)} to {name}",
                          f"light up {name}", f"switch {pick(r, LIGHTS)} to {name}", f"be {name}"])
        return prompt, f"rgb({c[0]}, {c[1]}, {c[2]})\n"
    if kind == "off":
        return pick(r, ["lights off", f"turn off {pick(r, LIGHTS)}", f"turn {pick(r, LIGHTS)} off", "kill the lights",
                        "lights out", "no lights", "dark mode"]), "rgb(0, 0, 0)\n"
    if kind == "on":
        return pick(r, ["lights on", "headlights on", "turn on your headlights", "turn your lights on",
                        "light the way", "it's dark, lights on", "i can't see, lights please"]), "rgb(255, 255, 255)\n"
    if kind == "police":
        return pick(r, ["police mode", "be a police car", "police lights", "nee naw", "wee woo wee woo",
                        "you're the police now", "siren lights", "be a cop car", "cop car", "cop mode", "sirens",
                        "turn on the siren", "be the police"]), \
            "while 1:\n    rgb(255, 0, 0)\n    tone(900, 300)\n    rgb(0, 0, 255)\n    tone(600, 300)\n"
    if kind == "hazard":
        n = r.randint(3, 6)
        p = pick(r, [f"hazard lights", "turn on your hazards", f"blink orange {times(r, n)}", "flash your hazards"])
        if "times" not in p and "twice" not in p and "thrice" not in p:
            n = 5
        return p, f"for i in range({n}):\n    rgb(255, 80, 0)\n    wait(400)\n    rgb(0, 0, 0)\n    wait(400)\n"
    names = ["red", "orange", "yellow", "green", "blue", "purple"]
    return pick(r, ["rainbow lights", "do a rainbow", "show me all your colours", "disco lights", "party lights",
                    "light up like a christmas tree", "christmas lights", "be colourful", "be colorful", "all the colours"]), \
        "for i in range(2):\n" + "".join(f"    rgb({COLOURS[c][0]}, {COLOURS[c][1]}, {COLOURS[c][2]})\n    wait(300)\n" for c in names) + "rgb(0, 0, 0)\n"


def c_honk(r):
    n = r.randint(1, 4)
    p = pick(r, ["honk", f"honk {times(r, n)}", "beep beep", "toot toot", "honk the horn",
                 "use your horn", "honk at them", "make some noise", f"toot {times(r, n)}", "honk honk"])
    if p in ("beep beep", "toot toot", "honk honk"):
        n = 2
    elif not any(t in p for t in (" times", "twice", "thrice")):
        n = 1
    return p, f"for i in range({n}):\n    beep(250)\n    wait(150)\n" if n > 1 else "beep(250)\n"


def _step(r):
    """One short move for a chain: (phrase, program)."""
    k = r.random()
    if k < 0.4:
        p, prog = c_drive(r)
    elif k < 0.7:
        p, prog = c_turn(r)
        if "spin" in p or "donut" in p or "360" in p or "twirl" in p:
            return _step(r)
    elif k < 0.8:
        p, prog = c_honk(r)
    elif k < 0.9:
        p, prog = c_lights(r)
        if "while 1" in prog:
            return _step(r)
    elif k < 0.85:
        side = pick(r, ["left", "right"])
        p, prog = pick(r, [f"look {side}", f"look to the {side}"]), f"look({-60 if side == 'left' else 60})\nwait(300)\n"
    elif k < 0.9:
        p, prog = pick(r, ["wave", "wave at me"]), WAVE
    elif k < 0.95:
        k2 = pick(r, ["wink", "heart", "angry", "surprised"])
        p, prog = pick(r, EYE_ASK[k2]), EYE_PROG[k2]
    else:
        p, prog = pick(r, ["beep boop", "chirp", "say something"]), CHIRP
    return p, prog


def c_combo(r):
    n = pick(r, [2, 2, 2, 3])
    steps = [_step(r) for _ in range(n)]
    if r.random() < 0.12:                    # "... and come back"
        steps[-1] = (pick(r, ["come back", "come back to me", "drive back", "come back here"]),
                     "move(60, 0, 0)\nwait(1500)\nstop()\n")
    elif r.random() < 0.15:                  # "... and go": the last step drives on until the next request
        steps[-1] = (pick(r, ["go", "go go", "drive on", "keep going", "go forward"]), "move(60, 0, 0)\n")
    glue = [pick(r, [" then ", " and then ", ", then ", " and ", ", ", " after that ", " and after that "]) for _ in range(n - 1)]
    prompt = steps[0][0] + "".join(g + s[0] for g, s in zip(glue, steps[1:]))
    return prompt, "".join(s[1] for s in steps)


REACT_WHEN = [  # (phrase, condition, sensor) - what the car reads and when it acts
    ("something is close", "distance() < 20", "distance"), ("something gets close", "distance() < 20", "distance"),
    ("someone comes near", "distance() < 30", "distance"), ("anything is closer than 10 cm", "distance() < 10", "distance"),
    ("it gets cold", "temp() < 20", "temp"), ("it's colder than 18 degrees", "temp() < 18", "temp"),
    ("it gets hot", "temp() > 28", "temp"), ("it's warmer than 25 degrees", "temp() > 25", "temp"),
    ("it gets humid", "humidity() > 70", "humidity"), ("the air is damp", "humidity() > 70", "humidity"),
    ("you see a line", "track() > 0", "track"), ("you're on the line", "track() == 3", "track"),
    ("you tilt", "tilt() > 20", "tilt"), ("someone picks you up", "tilt() > 30", "tilt"),
    ("someone bumps you", "shaken()", "shaken"), ("i shake you", "shaken()", "shaken"), ("i tap you", "shaken()", "shaken"),
]


def c_react(r):
    when, cond, _ = pick(r, REACT_WHEN)
    kind = pick(r, ["colour", "beep", "say", "face", "back", "stop"])
    if kind == "colour":
        name = pick(r, list(COLOURS))
        c = COLOURS[name]
        p = pick(r, [f"turn your lights {name} when {when}", f"glow {name} if {when}", f"when {when}, go {name}",
                     f"if {when} turn {name}"])
        return p, f"while 1:\n    if {cond}:\n        rgb({c[0]}, {c[1]}, {c[2]})\n    else:\n        rgb(0, 0, 0)\n    wait(50)\n"
    if kind == "beep":
        p = pick(r, [f"beep when {when}", f"honk if {when}", f"when {when}, beep", f"warn me when {when}",
                     f"make noise if {when}"])
        return p, f"while 1:\n    if {cond}:\n        beep(150)\n    wait(50)\n"
    if kind == "say":
        w = pick(r, ["hey!", "hi!", "brr", "hot!", "whoa", "wow", "ouch", "hello", "careful", "oops"])
        p = pick(r, [f"say {w} when {when}", f"write {w} if {when}", f"when {when}, show {w}", f"if {when} say {w}"])
        return p, f'while 1:\n    clear()\n    if {cond}:\n        text({cx(w)}, 28, "{w}")\n    wait(50)\n'
    if kind == "face":
        sad = r.random() < 0.5
        p = pick(r, [f"make a {'sad' if sad else 'happy'} face when {when}", f"{'frown' if sad else 'smile'} if {when}",
                     f"when {when}, look {'sad' if sad else 'happy'}"])
        return p, f"while 1:\n    clear()\n    if {cond}:\n" + "".join("        " + l + "\n" for l in face(sad=sad).splitlines()) + "    wait(50)\n"
    if kind == "back":
        p = pick(r, [f"back off when {when}", f"back up if {when}", f"when {when}, reverse a bit", f"run away if {when}"])
        return p, f"while 1:\n    if {cond}:\n        move(-60, 0, 0)\n        wait(800)\n        stop()\n    wait(50)\n"
    sp, v = spd(r, plain=0.5)
    p = pick(r, [f"drive forward and stop when {when}", f"go until {when}", f"drive{(' ' + sp) if sp else ''} until {when}",
                 f"keep going until {when}"])
    if not sp or sp not in p:
        v = 60
    return p, f"move({v}, 0, 0)\nwhile not ({cond}):\n    wait(20)\nstop()\n"


def c_face(r):
    kind = pick(r, ["happy", "sad", "say"])
    if kind == "say":
        w = word(r)[:21]
        q = pick(r, ['"', "'", "", ""])
        return pick(r, [f"say {q}{w}{q} on your screen", f"put {q}{w}{q} on your face", f"show {q}{w}{q} on your face",
                        f"write {q}{w}{q} on your screen", f"your screen should say {q}{w}{q}"]), say(w)
    sad = kind == "sad"
    return pick(r, [f"make a {'sad' if sad else 'happy'} face", f"look {'sad' if sad else 'happy'}",
                    f"{'frown' if sad else 'smile'}", f"show me a {'sad' if sad else 'happy'} face",
                    f"{'sad' if sad else 'happy'} face pls", f"be {'sad' if sad else 'happy'}"]), \
        f'eyes("{"sad" if sad else "happy"}")\nclear()\n' + face(sad=sad)


# ---- the robot: going (and changing speed) until told otherwise, eyes, voice, ears, head tilt, arm, back sensor,
# table edges, and an honest "can't" for what it has no hardware for
def c_go(r):
    kind = pick(r, ["go", "go", "go", "fast", "slow", "full", "back"])
    if kind == "go":
        return pick(r, ["go", "let's go", "go go go", "move", "drive", "vroom vroom", "come on, move", "move it",
                        "giddy up", "onward", "let's roll", "hit the road", "off you go", "go on", "start driving",
                        "keep going", "drive on", "okay buddy let's go", "chop chop", "get moving"]), "move(60, 0, 0)\n"
    if kind == "fast":
        p, v = pick(r, [("a little faster", 70), ("a bit faster", 70), ("faster", 80), ("go faster", 80),
                        ("speed up", 80), ("FASTER", 90), ("faster faster", 90), ("more speed", 80), ("step on it", 90),
                        ("hurry up", 85), ("quicker", 80), ("much faster", 95)])
        return p, f"move({v}, 0, 0)\n"
    if kind == "full":
        return pick(r, ["full speed ahead", "as fast as you can", "max speed", "go full speed", "zoom zoom"]), "move(100, 0, 0)\n"
    if kind == "slow":
        p, v = pick(r, [("a little slower", 45), ("a bit slower", 45), ("slower", 35), ("slow down", 35),
                        ("go slow", 30), ("go slower", 35), ("easy, slower", 35), ("not so fast", 45),
                        ("take it easy", 30), ("gently now", 30), ("slow it down", 35), ("much slower", 20),
                        ("crawl", 10), ("go slow, you're scaring the cat", 30)])
        return p, f"move({v}, 0, 0)\n"
    if r.random() < 0.3:
        sp, v = spd(r, plain=0)
        return pick(r, [f"go {sp}", f"drive {sp}", f"move {sp}", f"keep going {sp}"]), f"move({v}, 0, 0)\n"
    return pick(r, ["keep backing up", "reverse and keep going", "go backwards", "drive backwards", "back back back"]), \
        "move(-50, 0, 0)\n"


def c_eyes(r):
    kind = pick(r, list(EYE_ASK))
    return pick(r, EYE_ASK[kind]), EYE_PROG[kind]


