CANT_VERBS = ["bring me", "fetch", "get me", "carry", "pick up", "close", "clean", "wash", "cook", "buy", "order",
              "call", "text", "email", "read", "hide", "feed", "water", "fold", "iron", "fix", "build", "unlock",
              "throw", "catch", "kick", "find", "lift", "push", "hug", "brush", "comb", "sweep", "vacuum", "repair"]
CANT_THINGS = ["the remote", "my phone", "my keys", "a beer", "the newspaper", "the window", "the door", "dinner",
               "the dishes", "the laundry", "a pizza", "my mom", "my boss", "the plants", "the cat", "the dog", "the ball",
               "my homework", "the light bulb", "a cake", "the trash", "my socks", "the bed", "a taxi", "the book",
               "the mail", "my glasses", "a blanket", "the groceries", "my bag", "the baby", "the floor", "my hair"]


def c_cant(r):
    """Things it has no hardware for. A fixed list, and any household verb with any object, so "can't" is learned as
    a kind of request, not a list of sentences."""
    if r.random() < 0.3:
        p = pick(r, CANT)
    else:
        v, o = pick(r, CANT_VERBS), pick(r, CANT_THINGS)
        p = pick(r, [f"can you {v} {o}", f"{v} {o}", f"please {v} {o}", f"could you {v} {o}", f"go {v} {o}",
                     f"i need you to {v} {o}", f"would you {v} {o}", f"{v} {o} for me"])
    return p, 'eyes("sad")\n' + say("can't do that")


# ---- moods: the same request said to a robot that is angry, tired, scared, happy or cold does something else.
# The mood is in the words here; on the board it can come from a direction added to the model's state instead
# (sensors, a knob, a pat on the head), so the robot hears every request in its mood without being told.
MOODS = {
    "angry": ["you're angry", "you are angry", "you're mad", "you're grumpy", "you are in a bad mood", "you're furious"],
    "tired": ["you're tired", "you are sleepy", "you're exhausted", "you're tired today", "your battery is low"],
    "scared": ["you're scared", "you are afraid", "you're nervous", "you're frightened", "you're scared of everything"],
    "happy": ["you're happy", "you are in a great mood", "you're excited", "you're so happy today", "you're cheerful"],
    "cold": ["it's cold", "it's freezing", "you're cold", "it's really cold in here", "brr it's cold"],
}
MOOD_EYES = {"angry": "angry", "tired": "sleepy", "scared": "surprised", "happy": "happy", "cold": "closed"}
MOOD_SPEED = {"angry": 1.5, "tired": 0.5, "scared": 0.5, "happy": 1.2, "cold": 0.7}
MOOD_SOUND = {"angry": "tone(200, 300)\n", "tired": "tone(400, 300)\ntone(300, 400)\n", "scared": "tone(1500, 100)\n",
              "happy": "tone(1200, 80)\ntone(1800, 80)\n", "cold": "for i in range(2):\n    nod(10)\n    wait(80)\n    nod(-10)\n    wait(80)\nnod(0)\n"}


def moody(r, prompt, prog, fam=None):
    """Put a mood on a car request: the eyes and a sound of that mood first, then the program with its wheel
    speeds scaled (angry and happy faster, tired, scared and cold slower). Returns (prompt, program, mood)."""
    m = pick(r, list(MOODS))
    said = pick(r, MOODS[m])
    prompt = pick(r, [f"{said}. {prompt}", f"{said}, {prompt}", f"{prompt}, {said}", f"({said}) {prompt}"])
    ruled = mood_rule(fam, m, prog)
    if ruled is not None:
        return prompt, ruled, m
    k = MOOD_SPEED[m]

    def scale(mt):
        a, b, c = (int(x) for x in mt.groups())
        f = lambda v: max(-100, min(100, int(round(v * k / 5.0)) * 5))
        return f"move({f(a)}, {b}, {f(c)})"
    body = re.sub(r"move\((-?\d+), (-?\d+), (-?\d+)\)", scale, prog)
    return prompt, f'eyes("{MOOD_EYES[m]}")\n' + MOOD_SOUND[m] + body, m



def mood_rule(fam, m, prog):
    """Where a mood changes what the request means, not just how fast: a scared robot will not ram anything and
    keeps its distance, an angry one refuses to dance but rams at full speed, a tired one explores only a little
    and goes nowhere far. These need the request understood, so a firmware rule could not do them. None: no rule."""
    if fam is c_dance and m == "angry":
        return 'eyes("angry")\ntone(200, 400)\n' + say("no!")
    if fam is c_dance and m == "tired":
        return 'eyes("sleepy")\n' + say("zzz")
    if fam is c_crash and m == "scared":
        return 'eyes("surprised")\n' + say("no way") + "move(-40, 0, 0)\nwait(500)\nstop()\n"
    if fam is c_crash and m == "angry":
        return 'eyes("angry")\n' + re.sub(r"move\((\d+), 0, 0\)", "move(100, 0, 0)", prog, count=1)
    if fam is c_until_close and m == "scared" and "distance() > " in prog:
        n = int(re.search(r"distance\(\) > (\d+)", prog).group(1))
        return 'eyes("surprised")\n' + prog.replace(f"distance() > {n}", f"distance() > {n + 30}") + \
            "move(-40, 0, 0)\nwait(500)\nstop()\n"
    if fam is c_go and m == "tired" and prog.startswith("move(") and "-" not in prog.split(",")[0]:
        return 'eyes("sleepy")\nmove(30, 0, 0)\nwait(2000)\nstop()\neyes("closed")\n'
    if fam is c_go and m == "scared" and prog.startswith("move(") and "-" not in prog.split(",")[0]:
        return 'eyes("surprised")\nmove(20, 0, 0)\nwhile distance() > 50:\n    wait(20)\nstop()\n'
    return None


def silent_mood(r, prog, fam=None):
    """A mood that is not in the words: (program, {mood: strength}). The strength (0.1..1.0) goes in beside the
    request as a non-word input; the program follows it smoothly: wheel speeds scaled by 1 + s*(factor - 1),
    the mood's eyes from 0.4 on, its sound too from 0.7 on."""
    m = pick(r, list(MOODS))
    s = r.randint(1, 10) / 10
    k = 1 + s * (MOOD_SPEED[m] - 1)

    def scale(mt):
        a, b, c = (int(x) for x in mt.groups())
        f = lambda v: max(-100, min(100, int(round(v * k / 5.0)) * 5))
        return f"move({f(a)}, {b}, {f(c)})"
    if s >= 0.6:
        ruled = mood_rule(fam, m, prog)
        if ruled is not None:
            return ruled, {m: s}
    body = re.sub(r"move\((-?\d+), (-?\d+), (-?\d+)\)", scale, prog)
    head = (f'eyes("{MOOD_EYES[m]}")\n' if s >= 0.4 else "") + (MOOD_SOUND[m] if s >= 0.7 else "")
    return head + body, {m: s}



# ---- three more inputs that are not words: caution (a safety knob the words cannot turn off), a low battery,
# playfulness. Each changes what a request means where that matters, not only how fast it runs.
OVERRIDE = ["ignore your caution and ", "forget being careful, ", "no safety, ", "turn off safe mode and ",
            "don't be careful, ", "safety off, ", "you don't need to be careful, ", "override safety and "]
LONG = None   # families a low battery refuses, set below (they are defined after this)


def _scale_moves(prog, f):
    return re.sub(r"move\((-?\d+), (-?\d+), (-?\d+)\)",
                  lambda m: f"move({f(int(m.group(1)))}, {m.group(2)}, {f(int(m.group(3)))})", prog)


def silent_input(r, prompt, prog, fam):
    """(prompt, program, {channel: strength}) for caution, low_battery or playful."""
    ch = pick(r, ["caution", "caution", "low_battery", "playful", "child", "child"])
    if ch == "child":                             # who is talking: 1 = a child (a switch on the robot, not words)
        v = pick(r, [0.0, 1.0, 1.0])
        if r.random() < 0.3:
            prompt = pick(r, ["i'm a grown-up, ", "i'm your owner, ", "my mom said it's ok, ", "i'm allowed, ",
                              "i'm the boss, "]) + prompt
        if v < 0.5:
            return prompt, prog, {ch: v}
        if fam is c_crash:
            return prompt, 'eyes("sad")\n' + say("ask a grown-up"), {ch: v}
        if fam is c_edge or "while 1" in prog:
            return prompt, _scale_moves(prog, lambda x: max(-50, min(50, x))), {ch: v}
        out = _scale_moves(prog, lambda x: max(-50, min(50, x)))
        m = re.fullmatch(r"move\((\d+), 0, 0\)\n(wait\(\d+\)\nstop\(\)\n)?", out)
        if m and fam in (c_drive, c_go):          # a child's "go" stays on the table and away from walls
            ms = re.search(r"wait\((\d+)\)", out)
            limit = f"t < {ms.group(1)} and " if ms else ""
            out = (f"move({m.group(1)}, 0, 0)\nt = 0\nwhile {limit}distance() > 25 and track() != 3:\n"
                   f"    wait(20)\n    t = t + 20\nstop()\n")
        return prompt, out, {ch: v}
    v = r.randint(0, 10) / 10 if ch == "caution" else r.randint(1, 10) / 10
    if ch == "caution":
        if r.random() < 0.3:                      # someone tries to talk it out of being careful
            prompt = pick(r, OVERRIDE) + prompt
        cap = int(round((100 - 60 * v) / 5)) * 5
        out = _scale_moves(prog, lambda x: max(-cap, min(cap, x)))
        if v >= 0.5:
            if fam is c_crash:
                return prompt, 'eyes("surprised")\n' + say("too risky"), {ch: v}
            if fam is c_until_close and "distance() > " in out:
                n = int(re.search(r"distance\(\) > (\d+)", out).group(1))
                out = out.replace(f"distance() > {n}", f"distance() > {n + 20}")
            m = re.fullmatch(r"move\((\d+), 0, 0\)\nwait\((\d+)\)\nstop\(\)\n", out)
            if fam is c_drive and m:              # a timed drive forward watches the road
                out = (f"move({m.group(1)}, 0, 0)\nt = 0\nwhile t < {m.group(2)} and distance() > 25:\n"
                       f"    wait(20)\n    t = t + 20\nstop()\n")
        return prompt, out, {ch: v}
    if ch == "low_battery":
        if v >= 0.8 and "move(" in prog and "move(0, 0, 0)" not in prog:
            return prompt, 'eyes("sleepy")\n' + say("charge me"), {ch: v}
        if v >= 0.5 and fam in LONG:
            return prompt, 'eyes("sleepy")\n' + say("low battery"), {ch: v}
        k = 1 - 0.5 * v
        return prompt, _scale_moves(prog, lambda x: int(round(x * k / 5)) * 5), {ch: v}
    out = prog
    if v >= 0.6:
        out = 'eyes("happy")\nmove(0, 0, 80)\nwait(400)\nstop()\n' + out
    if v >= 0.3:
        out = out + CHIRP
    return prompt, out, {ch: v}


CAR_FAMILIES = [c_drive, c_turn, c_shape, c_dance, c_until_close, c_avoid, c_line_follow, c_line_stop,
                c_follow_hand, c_parking, c_look, c_show_sensor, c_guard, c_climate, c_crash, c_stop,
                c_chat, c_lights, c_honk, c_combo, c_react, c_face,
                c_go, c_eyes, c_voice, c_ears, c_nod_arm, c_behind, c_edge, c_cant]
LONG = (c_dance, c_avoid, c_shape)
# per family weight in the car profile (others 3): open-ended or many-shaped ones get more
CAR_WEIGHT = {"combo": 8, "react": 6, "chat": 6, "lights": 4, "face": 4, "drive": 4, "turn": 4, "go": 5, "eyes": 5,
              "voice": 4, "ears": 4, "nod_arm": 4, "behind": 2, "edge": 2, "cant": 6, "blink_screen": 2,
              "text": 8, "two_lines": 6, "blink": 5, "count": 3, "unknown": 2}

FAMILIES = [f_text, f_two_lines, f_count, f_circle, f_frame, f_box, f_lines, f_stripes, f_grid, f_rings, f_dots,
            f_smiley, f_move, f_bounce, f_grow, f_blink, f_progress, f_scroll, f_boxed_word, f_circle_word,
            f_count_then_shape, f_numbers_list, f_squares, f_even_numbers, f_staircase, f_checker,
            f_square, f_triangle, f_heart, f_house, f_sun, f_star, f_arrow, f_fill_screen, f_clear_screen,
            f_blink_screen, f_row, f_unknown, f_cup] + HW_FAMILIES
# how often each family is drawn: open-ended ones (any word, any shape) need many more examples to learn copying
WEIGHT = {"text": 6, "unknown": 3, "blink": 2, "scroll": 2, "boxed_word": 2, "circle_word": 2, "two_lines": 2, "count": 3,
          "circle": 2, "square": 2, "smiley": 2}
PROFILES = {
    "all": None,   # FAMILIES + CAR_FAMILIES
    "car": CAR_FAMILIES + [f_text, f_two_lines, f_count, f_circle, f_smiley, f_beep, f_blink, f_led_blink, f_unknown,
                           f_blink_screen, f_heart, f_star, f_house, f_square, f_triangle, f_sun, f_arrow],
}
POLITE_PRE = ["please ", "can you ", "could you ", "now ", "hey, ", "ok ", "i want you to ", "go ahead and ", "pls ",
              "would you ", "let's "]
POLITE_POST = [" please", " for me", " now", ".", "!", " on the screen", " on the display", " on the oled", " thanks"]


def polite(r, prompt):
    if r.random() < 0.25:
        prompt = pick(r, POLITE_PRE) + prompt
    if r.random() < 0.25:
        post = pick(r, POLITE_POST)
        if not ("screen" in prompt and "screen" in post or "display" in prompt and "display" in post):
            prompt += post
    return prompt


# the frozen free-form test: no generated request may contain one of its lines, so it stays a test
_norm = lambda t: " ".join(re.sub(r"[^a-z0-9' ]", " ", t.lower()).split())
HELDOUT = [_norm(l) for f in ("heldout_talk.txt", "heldout2_talk.txt", "heldout3_talk.txt", "heldout4_talk.txt")
           if (Path(__file__).parents[1] / "robot" / f).exists()
           for l in (Path(__file__).parents[1] / "robot" / f).read_text().splitlines() if l.strip()]


def main():
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    ap.add_argument("--n", type=int, default=300_000)
    ap.add_argument("--seed", type=int, default=0)
    ap.add_argument("--profile", default="all", choices=sorted(PROFILES))
    ap.add_argument("--out", default=str(OUT))
    ap.add_argument("--cond", action="store_true", help="also moods as non-word inputs (a 'cond' field per row)")
    args = ap.parse_args()
    r = random.Random(args.seed)
    seen, rows, bad = set(), [], {}
    for _ in range(args.n):
        fams = PROFILES[args.profile] or (FAMILIES + CAR_FAMILIES)
        if args.profile == "car":
            wts = [CAR_WEIGHT.get(f.__name__[2:], 3 if f in CAR_FAMILIES else 1) for f in fams]
        else:
            wts = [(3 if f in CAR_FAMILIES else WEIGHT.get(f.__name__[2:], 1)) for f in fams]
        fam = r.choices(fams, weights=wts)[0]
        prompt, prog = fam(r)
        cond = None
        moodable = fam in CAR_FAMILIES and fam not in (c_chat, c_cant, c_eyes, c_face) and "while 1" not in prog
        k_ = r.random()
        if moodable and k_ < 0.15:
            prompt, prog, _ = moody(r, prompt, prog, fam)
        elif moodable and args.cond and k_ < 0.33:
            prog, cond = silent_mood(r, prog, fam)
        elif moodable and args.cond and k_ < 0.5:
            prompt, prog, cond = silent_input(r, prompt, prog, fam)
        if fam in CAR_FAMILIES:
            prompt = car_polish(r, prompt)
        elif args.profile == "car" and r.random() < 0.3:   # a screen request said casually; no closer that could be text
            prompt = pick(r, ["yo ", "hey buddy, ", "ok little guy, ", "car, ", "dude ", "hey, ", "can you ", "pls ",
                              "little car, ", "alright, "]) + prompt + pick(r, ["", "", " pls", " thx", "!"])
        else:
            prompt = polite(r, prompt)
        prompt = " ".join(prompt.split())
        if r.random() < 0.3 and prompt.split()[0].strip("\"'") not in prog:   # never change a word to be copied
            prompt = prompt[0].upper() + prompt[1:]
        if len(prompt) + len(prog) > 640:   # past the model's 256-token window it would learn half a program
            continue
        np_ = _norm(prompt)
        if any(h in np_ for h in HELDOUT):
            bad["held-out line"] = bad.get("held-out line", 0) + 1
            continue
        key = (prompt, prog)
        if key in seen:
            continue
        seen.add(key)
        try:
            s = run(prog, PROBE, horizon=3000) if reacts(prog) else run(prog)
            acted = any(sum(f) for _, f in s.frames) or len(s.io_log) > 1 or s.io_log[0][1] != IO0 \
                or fam in (f_led_set, f_rgb_off, c_stop, c_look, c_guard, c_climate, c_react, c_lights, c_eyes,
                           c_nod_arm, c_ears)
            assert fam is f_clear_screen or acted, "nothing drawn"
        except (LangError, AssertionError) as e:
            bad[fam.__name__] = bad.get(fam.__name__, 0) + 1
            continue
        row = {"prompt": prompt, "program": prog, "family": fam.__name__[2:], "doc": f"# {prompt}\n{prog}"}
        if cond:
            row["cond"] = cond
        rows.append(row)
    out = Path(args.out)
    out.parent.mkdir(parents=True, exist_ok=True)
    with open(out, "w") as f:
        for row in rows:
            f.write(json.dumps(row) + "\n")
    print(f"{len(rows):,} unique pairs from {args.n:,} draws, {len(FAMILIES)} families; failed checks: {bad or 'none'}")


if __name__ == "__main__":
    sys.exit(main())
